// single-item input: one form submission, one prospect.
//
// Read the form by name: `Settings` sits between the two and a Set node in
// manual mode replaces the item, so $input here would be the config.
const f = $('Start An Audit').first().json;
const cfg = $('Settings').first().json;

function host(s) {
  return String(s || '').trim().toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '')
    .replace(/[\/?#].*$/, '');
}

const site = host(f['Their website']);
if (!site) {
  throw new Error('Enter the website you want audited, for example acme.com');
}

// The home page always, plus whatever paths are worth checking. Capped, because
// each one is a Bright Data call and an audit is a sample, not a crawl.
const paths = String(cfg.paths_to_check || '/')
  .split(',').map((p) => p.trim()).filter(Boolean).slice(0, 5);
if (paths.indexOf('/') === -1) paths.unshift('/');

return paths.map((p) => ({ json: {
  site,
  agency: String(f['Your agency name'] || '').trim() || 'This audit',
  path: p,
  page_url: 'https://' + site + (p === '/' ? '' : p),
  robots_url: 'https://' + site + '/robots.txt',
}}));

// single-item input: the loop hands over one page's HTML at a time.
//
// Raw HTML on purpose. Markdown is what every other template on this account
// asks for, and it strips exactly what an audit is about.
const item = $('Loop Over Pages').first().json;
const raw = $input.first().json;
const html = typeof raw === 'string' ? raw : (raw.data || raw.body || '');

// A domain that does not resolve returns an empty body rather than an error.
if (!html || html.length < 200) {
  return [{ json: {
    path: item.path, page_url: item.page_url, site: item.site,
    reachable: false, checks: [],
  }}];
}

function attr(tag, name) {
  const m = tag.match(new RegExp(name + '\\s*=\\s*["\']([^"\']*)["\']', 'i'));
  return m ? m[1].trim() : '';
}
function one(re) { const m = html.match(re); return m ? m[1].trim() : ''; }

const title = one(/<title[^>]*>([\s\S]{0,300}?)<\/title>/i);

let desc = '';
const META = /<meta\b[^>]*>/gi;
const metas = html.match(META) || [];
for (const m of metas) {
  if (/name\s*=\s*["']description["']/i.test(m)) desc = attr(m, 'content');
}
const viewport = metas.some((m) => /name\s*=\s*["']viewport["']/i.test(m));
const robotsMeta = metas
  .filter((m) => /name\s*=\s*["']robots["']/i.test(m))
  .map((m) => attr(m, 'content').toLowerCase()).join(' ');

const canonical = (() => {
  const links = html.match(/<link\b[^>]*>/gi) || [];
  for (const l of links) if (/rel\s*=\s*["']canonical["']/i.test(l)) return attr(l, 'href');
  return '';
})();

const h1s = (html.match(/<h1\b[^>]*>([\s\S]{0,200}?)<\/h1>/gi) || [])
  .map((h) => h.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim())
  .filter(Boolean);

const imgs = html.match(/<img\b[^>]*>/gi) || [];
const withAlt = imgs.filter((i) => attr(i, 'alt').length > 0).length;

const hasSchema = /application\/ld\+json/i.test(html);
const httpsMixed = (html.match(/(?:src|href)\s*=\s*["']http:\/\//gi) || []).length;

// Body words, with script and style removed first so a bundle is not counted as
// prose. Reported, but flagged as unreliable on a client-rendered page.
const bodyText = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const words = bodyText ? bodyText.split(' ').length : 0;

function check(id, label, ok, found, why) {
  return { id, label, status: ok === null ? 'n/a' : (ok ? 'pass' : 'fail'), found, why };
}

const checks = [
  check('title', 'Title tag', !!title && title.length >= 15 && title.length <= 65,
        title || '(none)',
        'Between about 15 and 65 characters so it is neither empty nor cut off in results.'),
  check('description', 'Meta description', !!desc && desc.length >= 50 && desc.length <= 165,
        desc ? desc.slice(0, 120) : '(none)',
        'Missing or over-long descriptions get rewritten by the search engine.'),
  check('h1', 'Exactly one H1', h1s.length === 1, h1s.length + ' found',
        'One H1 states what the page is. None leaves it ambiguous; several compete.'),
  check('canonical', 'Canonical link', !!canonical, canonical || '(none)',
        'Without it, duplicate URLs of the same page compete with each other.'),
  check('robots_meta', 'Not blocked by meta robots', !/noindex/.test(robotsMeta),
        robotsMeta || '(none set)',
        'A stray noindex removes the page from search entirely.'),
  check('viewport', 'Mobile viewport', viewport, viewport ? 'present' : '(none)',
        'Without it, phones render the desktop layout scaled down.'),
  // Phrased as the count that is *wrong*, not the count that is right. "6 of
  // 19" was read by the model as six images missing alt text when six was the
  // number that had it, and that inversion went straight into a report meant
  // for a prospect.
  check('alt', 'Images have alt text', imgs.length ? withAlt === imgs.length : null,
        imgs.length
          ? (imgs.length - withAlt) + ' of ' + imgs.length + ' images have no alt text'
          : 'no images on the page',
        'Alt text is what a screen reader and an image search both read.'),
  check('schema', 'Structured data', hasSchema, hasSchema ? 'JSON-LD present' : '(none)',
        'Structured data is how rich results are built.'),
  check('mixed', 'No insecure assets', httpsMixed === 0,
        httpsMixed ? httpsMixed + ' http:// references' : 'none',
        'Assets loaded over http on an https page get blocked by the browser.'),
];

return [{ json: {
  site: item.site, path: item.path, page_url: item.page_url,
  reachable: true, bytes: html.length, words,
  title, description: desc, canonical, h1_count: h1s.length,
  images: imgs.length, images_with_alt: withAlt,
  checks,
}}];

// Every page the loop audited, in one item.
//
// This node exists because of a trap that silently halves an audit:
// `$('Read The Page').all()` returns only the *most recent run* of that node,
// and inside a Split In Batches loop it runs once per page. Reading it from the
// scoring node reported a three-page audit as a one-page audit, scored the last
// page only, and looked completely successful.
//
// The loop's `done` output is the reliable place: it carries every item that
// was fed back round, so $input here is all of them.
const pages = $input.all().map((x) => x.json).filter((p) => p && p.site);
return [{ json: { pages, page_count: pages.length } }];

// single-item input: one robots.txt.
//
// Small, nearly always present, and the highest-stakes file on the site. A
// `Disallow: /` promoted from a staging config removes the whole domain from
// search and almost nobody notices for weeks.
const req = $('Read The Request').first().json;
const raw = $input.first().json;
const body = typeof raw === 'string' ? raw : (raw.data || raw.body || '');
const text = String(body || '');

const found = text.length > 0 && !/^\s*<!doctype|^\s*<html/i.test(text);

// Only the group that applies to everyone. A Disallow under a named bot is that
// bot's problem, not the site's.
let inStar = false;
let blocksEverything = false;
const disallows = [];
for (const line of text.split(/\r?\n/)) {
  const l = line.trim();
  if (/^user-agent\s*:/i.test(l)) {
    inStar = /^user-agent\s*:\s*\*\s*$/i.test(l);
    continue;
  }
  if (!inStar) continue;
  const m = l.match(/^disallow\s*:\s*(\S*)\s*$/i);
  if (m) {
    if (m[1] === '/') blocksEverything = true;
    if (m[1]) disallows.push(m[1]);
  }
}

const sitemaps = (text.match(/^sitemap\s*:\s*(\S+)/gim) || [])
  .map((l) => l.split(/:\s*/).slice(1).join(':').trim());

return [{ json: {
  site: req.site,
  robots_found: found,
  robots_blocks_everything: blocksEverything,
  robots_disallow_count: disallows.length,
  robots_disallows: disallows.slice(0, 8),
  sitemaps: sitemaps.slice(0, 3),
  has_sitemap: sitemaps.length > 0,
}}];

// Count the findings. No editorialising here - the model gets numbers.
const req = $('Read The Request').first().json;
const robots = $('Read The Robots File').first().json;
const pages = $('Collect The Pages').first().json.pages || [];

const reachable = pages.filter((p) => p.reachable);

// Roll the per-page checks up by check id, so the report can say "3 of 4 pages"
// rather than repeating the same finding four times.
const byCheck = {};
for (const p of reachable) {
  for (const c of p.checks) {
    const e = byCheck[c.id] || (byCheck[c.id] = {
      id: c.id, label: c.label, why: c.why, pass: 0, fail: 0, na: 0, examples: [],
    });
    if (c.status === 'pass') e.pass++;
    else if (c.status === 'fail') { e.fail++; if (e.examples.length < 3) e.examples.push({ path: p.path, found: c.found }); }
    else e.na++;
  }
}

const findings = Object.keys(byCheck).map((k) => byCheck[k]);
const failing = findings.filter((f) => f.fail > 0);

// Site-wide findings sit outside the per-page roll-up.
const siteFindings = [];
if (!robots.robots_found) {
  siteFindings.push({ label: 'robots.txt', status: 'fail', found: 'not found',
    why: 'Search engines look for it on every crawl; without one you are relying on defaults.' });
} else if (robots.robots_blocks_everything) {
  siteFindings.push({ label: 'robots.txt blocks the whole site', status: 'fail',
    found: 'Disallow: / for all crawlers',
    why: 'This removes the entire domain from search. It is almost always a staging config that reached production.' });
} else {
  siteFindings.push({ label: 'robots.txt', status: 'pass',
    found: robots.robots_disallow_count + ' disallow rule(s)', why: 'Present and not blocking everything.' });
}
siteFindings.push({
  label: 'Sitemap declared in robots.txt',
  status: robots.has_sitemap ? 'pass' : 'fail',
  found: robots.has_sitemap ? robots.sitemaps[0] : '(none)',
  why: 'A declared sitemap is the cheapest way to get new pages found.',
});

const totalChecks = findings.reduce((n, f) => n + f.pass + f.fail, 0) +
  siteFindings.filter((f) => f.status !== 'n/a').length;
const totalPass = findings.reduce((n, f) => n + f.pass, 0) +
  siteFindings.filter((f) => f.status === 'pass').length;
const score = totalChecks ? Math.round((totalPass / totalChecks) * 100) : 0;

// A site that blocks everything cannot be a healthy score whatever else passes.
const capped = robots.robots_blocks_everything ? Math.min(score, 35) : score;

return [{ json: {
  site: req.site,
  agency: req.agency,
  pages_checked: reachable.length,
  pages_unreachable: pages.length - reachable.length,
  score: capped,
  findings,
  failing_count: failing.length,
  site_findings: siteFindings,
  robots,
  pages: reachable.map((p) => ({
    path: p.path, title: p.title, words: p.words,
    images: p.images, images_with_alt: p.images_with_alt,
  })),
  audited_at: $now.toISO(),
}}];

parameters.text:
=You are a technical consultant writing the opening of a short site audit that will be sent to the site's owner, who did not ask for it.

Site: {{ $json.site }}
Pages checked: {{ $json.pages_checked }}
Score: {{ $json.score }} out of 100
Checks that failed somewhere:
{{ JSON.stringify($json.findings.filter(f => f.fail > 0)) }}
Site-wide findings:
{{ JSON.stringify($json.site_findings) }}

Write 60 to 100 words. Lead with the single finding that costs them the most, say plainly what it does, and name the number behind it. Then one sentence on what is already fine, because an audit that is all criticism reads as a sales pitch and gets deleted.

Use only the findings above. Do not invent a traffic figure, a ranking, a competitor or a revenue impact - none of that was measured. If nothing failed, say so directly rather than manufacturing a concern.

Plain prose, no headings, no bullets, no markdown emphasis. Do not open with a greeting or the site's name.

