// single-item input: the summary chain runs executeOnce, so it emits one
// paragraph for the one site being audited.
//
// The file they download. Self-contained HTML with inline styles, because it
// will be opened from a downloads folder and emailed on, with no server behind
// it and no stylesheet to fetch.
const d = $('Score The Site').first().json;
let summary = '';
try { summary = String($input.first().json.text || '').trim(); } catch (e) { summary = ''; }

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

const F = 'system-ui,-apple-system,Segoe UI,Roboto,sans-serif';
const band = d.score >= 80 ? '#0a7d33' : d.score >= 55 ? '#b45309' : '#b91c1c';

function row(label, status, found, why) {
  const colour = status === 'pass' ? '#0a7d33' : status === 'fail' ? '#b91c1c' : '#6b7280';
  const mark = status === 'pass' ? 'PASS' : status === 'fail' ? 'FAIL' : 'N/A';
  return '<tr>' +
    '<td style="padding:10px 12px;border-bottom:1px solid #eee;vertical-align:top">' +
    '<b>' + esc(label) + '</b><div style="color:#555;font-size:13px;margin-top:2px">' + esc(why) + '</div></td>' +
    '<td style="padding:10px 12px;border-bottom:1px solid #eee;vertical-align:top;white-space:nowrap">' +
    '<span style="color:' + colour + ';font-weight:700;font-size:12px">' + mark + '</span></td>' +
    '<td style="padding:10px 12px;border-bottom:1px solid #eee;vertical-align:top;color:#333;font-size:13px">' +
    esc(found) + '</td></tr>';
}

const perCheck = d.findings.map((f) => {
  const status = f.fail > 0 ? 'fail' : (f.pass > 0 ? 'pass' : 'n/a');
  const found = f.fail > 0
    ? f.fail + ' of ' + (f.pass + f.fail) + ' pages: ' +
      f.examples.map((e) => e.path + ' (' + String(e.found).slice(0, 60) + ')').join('; ')
    : (f.pass > 0 ? 'all ' + f.pass + ' pages' : 'not applicable');
  return row(f.label, status, found, f.why);
}).join('');

const perSite = d.site_findings.map((f) => row(f.label, f.status, f.found, f.why)).join('');

const pageList = d.pages.map((p) =>
  '<li style="margin-bottom:4px"><code>' + esc(p.path) + '</code> - ' +
  esc(String(p.title || '(no title)').slice(0, 70)) +
  ' <span style="color:#777">(' + p.words + ' words, ' +
  p.images_with_alt + '/' + p.images + ' images with alt)</span></li>').join('');

const html =
'<!doctype html><html><head><meta charset="utf-8">' +
'<title>Site audit - ' + esc(d.site) + '</title></head>' +
'<body style="margin:0;background:#f6f7f9;font:15px/1.6 ' + F + ';color:#111">' +
'<div style="max-width:820px;margin:0 auto;padding:32px 24px">' +
'<div style="background:#fff;border-radius:12px;padding:28px 30px">' +
'<div style="color:#666;font-size:13px;letter-spacing:.08em;text-transform:uppercase">' +
esc(d.agency) + '</div>' +
'<h1 style="font-size:26px;margin:6px 0 2px">Site audit: ' + esc(d.site) + '</h1>' +
'<div style="color:#666;font-size:13px">' + d.pages_checked + ' page' +
(d.pages_checked === 1 ? '' : 's') + ' checked - ' + esc(String(d.audited_at).slice(0, 10)) + '</div>' +
'<div style="margin:22px 0;padding:16px 18px;background:#f6f7f9;border-radius:8px;display:flex;align-items:center;gap:18px">' +
'<div style="font:700 34px ' + F + ';color:' + band + '">' + d.score + '<span style="font-size:15px;color:#888">/100</span></div>' +
'<div style="font-size:14px;color:#333">' + d.failing_count + ' check' +
(d.failing_count === 1 ? '' : 's') + ' failing on at least one page</div></div>' +
(summary ? '<p style="font-size:15px">' + esc(summary) + '</p>' : '') +
'<h2 style="font-size:17px;margin:26px 0 8px">Site-wide</h2>' +
'<table style="width:100%;border-collapse:collapse">' + perSite + '</table>' +
'<h2 style="font-size:17px;margin:26px 0 8px">Per page</h2>' +
'<table style="width:100%;border-collapse:collapse">' + perCheck + '</table>' +
'<h2 style="font-size:17px;margin:26px 0 8px">Pages checked</h2>' +
'<ul style="font-size:14px;padding-left:20px;margin:0">' + pageList + '</ul>' +
'<p style="color:#888;font-size:12px;margin-top:26px">' +
'Measured from the HTML each page returned. Content rendered by JavaScript in the ' +
'browser is not visible to this check, so word counts on a single-page app are ' +
'indicative rather than exact.</p>' +
'</div></div></body></html>';

return [{ json: {
  site: d.site,
  score: d.score,
  failing_count: d.failing_count,
  pages_checked: d.pages_checked,
  audited_at: d.audited_at,
  file_name: 'site-audit-' + String(d.site).replace(/[^a-z0-9.-]/gi, '-') + '.html',
  report_html: html,
}}];
